private theorem phaseDistances_nonempty (x y : X) :
    {r : ℝ | ∃ θ ∈ unitScalars, r = ‖x - θ • y‖}.Nonempty := by
  exact ⟨‖x - (1 : ℂ) • y‖, 1, one_mem_unitScalars, rfl⟩

